DATA_PFLICHT = ["name", "zweck", "herkunft", "lizenz", "n_beispiele", "bekannte_luecken"]
MODELL_PFLICHT = ["name", "zweck", "version", "trainingsdaten", "metrik", "schwellenwert", "bekannte_grenzen"]
SYSTEM_PFLICHT = ["modell", "metrik", "schwelle", "kontrolle"]


def cross_card_consistency(datacard, modelcard, systemcard, protocol):
    befunde = []
    namen = {datacard.get("name"), modelcard.get("trainingsdaten"), protocol.get("datensatz")}
    if len(namen) > 1:
        befunde.append("datensatz-unstimmig")
    metriken = {datacard.get("metrik"), modelcard.get("metrik"), systemcard.get("metrik"), protocol.get("metrik")}
    if len(metriken) > 1:
        befunde.append("metrik-unstimmig")
    if modelcard.get("name") != systemcard.get("modell"):
        befunde.append("modell-unstimmig")
    if modelcard.get("schwellenwert") != systemcard.get("schwelle"):
        befunde.append("schwelle-unstimmig")
    if datacard.get("n_beispiele") != protocol.get("n_beispiele"):
        befunde.append("umfang-unstimmig")
    for label, karte, pflicht in (("datacard", datacard, DATA_PFLICHT), ("modelcard", modelcard, MODELL_PFLICHT), ("systemcard", systemcard, SYSTEM_PFLICHT)):
        for feld in pflicht:
            wert = karte.get(feld)
            if wert is None or str(wert).strip() == "":
                befunde.append(label + "." + feld + "-fehlt")
    return sorted(set(befunde))

